Lemma aden_rg_u : forall j rg off, nth_error (c_rgs C) j = Some rg -> rg_lo rg <= off < rg_hi rg ->
  bv_unsigned (aden (ARg j off)) = rbase rg + off /\ c_abs_hi C <= rbase rg + off < 2 ^ 64.
